import type { ModalProps } from "./modal.types";
import type { CSSObject } from "@emotion/react";

import styled from "@emotion/styled";
import { keyframes } from "@emotion/react";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import * as RadixDialog from "@radix-ui/react-dialog";
import { useMemo } from "react";

const componentName = "Modal";

export const ModalClasses = {
  root: "exp-textura_modal",
  sm: "exp-textura_modal_sm",
  md: "exp-textura_modal_md",
  body: "exp-textura_modal_body",
  title: "exp-textura_modal_title",
  content: "exp-textura_modal_content",
  divider: "exp-textura_modal_divider",
  footer: "exp-textura_modal_footer",
  overlay: "exp-textura_modal_overlay",
  closeIconButton: "exp-textura_modal_close_icon_button",
};

// Set up style variant settings for the component (if more than "default"), using style slots
// const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
//   exampleVariant: { root: { backgroundColor: theme.color.background.default } },
// });

const generateStyles = (props: Omit<ModalProps, "children">): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<ModalProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        // getVariantConfig(),
      ),
    [theme, variant, styleSlotsProp],
  );

  const fadeInOverlay = keyframes`from { opacity: 0; } to { opacity: ${styleSlots?.overlay?.opacity}; }`;
  const fadeOutOverlay = keyframes`from { opacity: ${styleSlots?.overlay?.opacity}; } to { opacity: 0; }`;

  const fadeInModal = keyframes`from { opacity: 0; } to { opacity: 1; }`;
  const fadeOutModal = keyframes`from { opacity: 1; } to { opacity: 0; }`;

  return {
    [`&.${ModalClasses.overlay}`]: {
      position: "fixed",
      inset: 0,
      animationTimingFunction: "ease",
      animationFillMode: "forwards",
      backgroundColor: theme.overlay.background,
      zIndex: theme.zIndex.dynamic,
      animationDuration: "100ms",
      '&[data-state="open"]': {
        animationName: fadeInOverlay,
        opacity: styleSlots?.overlay?.opacity,
      },
      '&[data-state="closed"]': {
        animationName: fadeOutOverlay,
        opacity: 0,
      },
      '&[data-textura-scoped="true"]': {
        position: "absolute",
      },
      ...styleSlots?.overlay,
    },

    [`&.${ModalClasses.sm}`]: {
      width: theme.toRem(576),
    },

    [`&.${ModalClasses.md}`]: {
      width: theme.toRem(752),
    },

    [`&.${ModalClasses.body}`]: {
      display: "flex",
      flexDirection: "column",
      position: "fixed",
      top: "50%",
      left: "50%",
      transform: "translate(-50%, -50%)",
      opacity: 1,
      animationTimingFunction: "ease",
      animationFillMode: "forwards",
      animationDuration: "100ms",
      backgroundColor: theme.dialog.color.background,
      color: theme.dialog.color.content,
      boxShadow: theme.dropShadow.lg,
      borderRadius: theme.toRem(theme.border.radius.sm),
      overflowY: "auto",
      padding: `${theme.toRem(theme.spacing[16])} 0`,
      maxWidth: `calc(100vw - ${theme.toRem(80)})`,
      maxHeight: `calc(100% - ${theme.toRem(80)})`,
      zIndex: theme.zIndex.dynamic,
      ...theme.typography.body.md,
      '&[data-state="open"]': {
        animationName: fadeInModal,
        opacity: 1,
      },
      [`&[data-state="closed"]`]: {
        animationName: fadeOutModal,
      },
      '&[data-textura-scoped="true"]': {
        position: "absolute",
      },
      ...styleSlots?.body,
    },

    [`& .${ModalClasses.content}`]: {
      flex: "1 1 auto",
      overflowY: "auto",
      padding: theme.toRem(theme.spacing[24]),
      ...theme.typography.body.md,
      ...styleSlots?.content,
    },

    [`& .${ModalClasses.footer}`]: {
      padding: `${theme.toRem(theme.spacing[16])} ${theme.toRem(theme.spacing[24])} 0 ${theme.toRem(theme.spacing[24])}`,
      ...styleSlots?.footer,
    },

    [`& .${ModalClasses.title}`]: {
      ...theme.typography.heading.sm,
      margin: 0,
      color: theme.dialog.color.content,
      padding: `0 ${theme.toRem(theme.spacing[24])} ${theme.toRem(theme.spacing[16])}`,
      ...styleSlots?.title,
    },

    [`& .${ModalClasses.divider}`]: {
      backgroundColor: theme.divider.default.color.default,
      ...styleSlots?.divider,
    },

    [`& .${ModalClasses.closeIconButton}`]: {
      position: "absolute",
      top: theme.toRem(theme.spacing[16]),
      right: theme.toRem(theme.spacing[16]),
      display: "inline-flex",
      alignItems: "center",
      justifyContent: "center",
      padding: theme.toRem(theme.spacing[8]),
      fontSize: theme.typography.fontSize[16],
      ":dir(rtl)": {
        right: "unset",
        left: theme.toRem(theme.spacing[16]),
      },
      "&:focus-visible": {
        ...styleSlots?.closeIconButtonFocus,
      },
      ...styleSlots?.closeIconButton,
    },

    ...styleSlots?.root,
  };
};

const excludedDOMProps = getExcludedDOMProps();

export const StyledModal = styled(RadixDialog.Content, {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<Omit<ModalProps, "children">>((props) => generateStyles(props));

export const StyledModalOverlay = styled(RadixDialog.Overlay, {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<Omit<ModalProps, "children">>((props) => generateStyles(props));
